// The holes: geometry for the physics, the surface map, the animals, and the art. The data is generated by
// art/game/tools/holes.py into course_data.cpp; this header is the shape of it.
#pragma once

#include <stdint.h>

#include "gfx.h"

namespace game {

// What the ball is rolling on. One byte per screen pixel in the decoded surface map.
enum Surface : uint8_t {
  kFelt = 0,
  kSand = 1,     // slows the ball hard
  kWater = 2,    // splash: back to where the stroke was taken, plus one stroke
  kIce = 3,      // barely slows it
  kSlope0 = 4,   // kSlope0 + d: a slope pushing towards direction d (0 = east, counter-clockwise in 45° steps
                 // on screen, so 2 = up the screen)
  kOut = 12,     // outside the course (behind the rails); treated as a wall if the ball ever gets there
};

struct Seg {
  int16_t x1, y1, x2, y2;  // a rail, in screen pixels
};

struct Bumper {
  int16_t x, y;
  uint8_t r;
  uint8_t bounce;  // restitution x 100 (e.g. 120 for a springy mushroom)
};

enum class AnimalKind : uint8_t;  // defined with the art (assets.h)

enum class Motion : uint8_t {
  Walk,   // glides along the path and back
  Hop,    // hops from point to point; the ball passes under it while it is in the air
  Pop,    // appears at one point, waits, ducks down, appears at the next (seal at ice holes)
  Sleep,  // stays put and breathes; rolls over when hit
};

struct AnimalDef {
  uint8_t kind;           // index into the animal art table
  Motion motion;
  uint8_t radius;         // collision radius in pixels
  uint8_t speed;          // pixels per second (walk) or hops per 10 s (hop)
  uint8_t pointCount;
  const int16_t* points;  // x,y pairs
};

struct Hole {
  const char* name;      // short, shown on the hole card
  uint8_t par;
  uint8_t habitat;       // index into the habitat table
  uint8_t unlockDay;     // days after hatching
  int16_t teeX, teeY, cupX, cupY;
  const Seg* segs;
  uint16_t segCount;
  const Bumper* bumpers;
  uint8_t bumperCount;
  const AnimalDef* animals;
  uint8_t animalCount;
  const uint8_t* surface;  // RLE: (count-1, code) byte pairs over 135x240, row by row
  uint32_t surfaceSize;
  const gfx::Packed* art;  // the painted hole, without animals
  const char* fact;        // the animal fact card, lines split by '\n'
};

struct Habitat {
  const char* name;
  uint16_t accent;  // swapped-565, the habitat's signature colour for cards and the HUD
};

extern const Hole kHoles[];
extern const uint8_t kHoleCount;
extern const Habitat kHabitats[];
extern const uint8_t kHabitatCount;

// Decodes a hole's RLE surface into a 135x240 byte map.
void decodeSurface(const Hole& h, uint8_t* out);

}  // namespace game
